class InstgenVerdictTests(unittest.TestCase):
    def test_the_real_pass_transcript_passes(self):
        report = verdict(REAL_INSTGEN_PASS_TRANSCRIPT, reached=True)
        self.assertEqual(report["problems"], [])
        self.assertEqual(report["verdict"], "PASS")

    def test_a_flat_netboot_fails_on_the_path_assertion_alone(self):
        report = verdict(REAL_FLAT_NAME_TRANSCRIPT, reached=True)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertEqual(report["problems"],
                         ["missing path-structured netboot fetch"])

    def test_no_real_run_carries_a_failure_marker(self):
        self.assertEqual(
            failure_markers_present(REAL_INSTGEN_PASS_TRANSCRIPT), [])
        self.assertEqual(
            failure_markers_present(REAL_FLAT_NAME_TRANSCRIPT), [])

    def test_an_early_death_misses_everything(self):
        missing = missing_assertions(REAL_NEVER_REACHED_PREFIX)
        for name, _ in ASSERTIONS:
            self.assertIn(name, missing)
        report = verdict(REAL_NEVER_REACHED_PREFIX, reached=False)
        self.assertEqual(report["verdict"], "FAIL")

    def test_a_run_stopping_short_of_the_final_pass_is_named(self):
        # The real transcript truncated right before its final
        # pass-report line: everything else present, the end missing.
        index = REAL_INSTGEN_PASS_TRANSCRIPT.rfind(
            "Instgen: Starting PASS  1000")
        clipped = REAL_INSTGEN_PASS_TRANSCRIPT[:index]
        report = verdict(clipped, reached=False)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertIn("missing final pass", report["problems"])
        self.assertIn("missing instgen completion", report["problems"])


if __name__ == "__main__":
    unittest.main()
